text:
.modal-container[data-v-b19c9e70] {
  width: 100%;
  max-width: 580px;
  display: flex;
  flex-direction: column;
  max-height: 90vh;
}
.modal-header[data-v-b19c9e70] {
  padding: 1.5rem 2rem 1rem;
  border-bottom: 1px solid #e5e7eb;
}
.header-content[data-v-b19c9e70] {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}
.header-left[data-v-b19c9e70] {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.step-indicator[data-v-b19c9e70] {
  font-size: 0.75rem;
  font-weight: 600;
  color: #6b7280;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.modal-title[data-v-b19c9e70] {
  font-size: 1.5rem;
  font-weight: 600;
  color: #111827;
  line-height: 1.3;
  margin: 0;
}
.modal-content[data-v-b19c9e70] {
  padding: 1.5rem 2rem;
  flex: 1;
}
.error-banner[data-v-b19c9e70] {
  background-color: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: 8px;
  padding: 1rem;
  margin-bottom: 1.5rem;
}
.error-text[data-v-b19c9e70] {
  color: #dc2626;
  font-size: 0.875rem;
  font-weight: 500;
}
.modal-footer[data-v-b19c9e70] {
  padding: 1.25rem 2rem 1.5rem;
  border-top: 1px solid #e5e7eb;
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
}
.button[data-v-b19c9e70] {
  padding: 0.625rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 100px;
  justify-content: center;
}
.button[data-v-b19c9e70]:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.button-secondary[data-v-b19c9e70] {
  background: white;
  color: #374151;
  border: 1px solid #d1d5db;
}
.button-secondary[data-v-b19c9e70]:hover:not(:disabled) {
  background: #f9fafb;
  border-color: #9ca3af;
}
.button-primary[data-v-b19c9e70] {
  background: #0060df;
  color: white;
}
.button-primary[data-v-b19c9e70]:hover:not(:disabled) {
  background: #0050c8;
}
.loading-spinner[data-v-b19c9e70] {
  display: inline-block;
  width: 14px;
  height: 14px;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-top-color: white;
  border-radius: 50%;
  animation: spin-b19c9e70 0.6s linear infinite;
}
@keyframes spin-b19c9e70 {
to {
    transform: rotate(360deg);
}
}

/* Responsive adjustments */
@media (max-width: 640px) {
.modal-container[data-v-b19c9e70] {
    max-width: 100%;
    margin: 0.5rem;
}
.modal-header[data-v-b19c9e70] {
    padding: 1.25rem 1.5rem 0.875rem;
}
.modal-content[data-v-b19c9e70] {
    padding: 1.25rem 1.5rem;
}
.modal-footer[data-v-b19c9e70] {
    padding: 1rem 1.5rem 1.25rem;
    flex-direction: column-reverse;
}
.button[data-v-b19c9e70] {
    width: 100%;
}
.modal-title[data-v-b19c9e70] {
    font-size: 1.25rem;
}
}
